<script setup lang="ts">
import { computed, ref, useId } from 'vue'
const id=useId()
const query=ref('')
const species=ref('all')
const selected=ref('sample-dog')
const pets=[{id:'sample-dog',name:'Kiara',species:'Dog',description:'Labrador mix, 4 years',status:'Vaccines up to date',note:'Illustrative recorded-status label, not verified health evidence.',initial:'K'},{id:'sample-cat',name:'Miso',species:'Cat',description:'Domestic shorthair, 2 years',status:'Booster due soon',note:'Sample reminder wording only; no notification is set.',initial:'M'},{id:'sample-rabbit',name:'Pip',species:'Rabbit',description:'Holland lop rabbit, 1 year',status:'Checkup overdue',note:'Fictitious status, not a diagnosis or recommendation.',initial:'P'}]
const visible=computed(()=>pets.filter(p=>(species.value==='all'||p.species===species.value)&&p.name.toLowerCase().includes(query.value.trim().toLowerCase())))
const current=computed(()=>pets.find(p=>p.id===selected.value)!)
function reset(){query.value='';species.value='all';selected.value='sample-dog'}
</script>
<template>
<section class="pet-profile-demo" aria-label="Pet profile cards example"><p>Fictitious pets and statuses. Selection changes local details only.</p><div class="pet-filters"><label>Find sample pet<input v-model="query" type="search" maxlength="60"></label><label>Species<select v-model="species"><option value="all">All species</option><option>Dog</option><option>Cat</option><option>Rabbit</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="pet-grid"><article v-for="pet in visible" :key="pet.id" :aria-label="pet.name+' profile'"><div class="pet-avatar" aria-hidden="true">{{ pet.initial }}</div><h3>{{ pet.name }}</h3><p>{{ pet.description }}</p><p class="pet-status">{{ pet.status }}</p><button type="button" :aria-pressed="selected===pet.id" :aria-controls="id+'-detail'" :aria-label="'Select '+pet.name" @click="selected=pet.id">{{ selected===pet.id?'Selected':'View local details' }}</button></article></div><p v-if="!visible.length" class="pet-empty">No matching sample pets. Clear the name or choose All species.</p><p role="status">{{ visible.length }} matching sample pets. Selected: {{ current.name }}.</p><section :id="id+'-detail'" class="pet-detail" :key="current.id" :aria-label="current.name+' local details'"><h3>{{ current.name }}: local details</h3><dl><div><dt>Sample ID</dt><dd>{{ current.id }}</dd></div><div><dt>Species</dt><dd>{{ current.species }}</dd></div><div><dt>Sample status</dt><dd>{{ current.status }}</dd></div></dl><p>{{ current.note }}</p><p v-if="!visible.some(p=>p.id===selected)" class="pet-hidden">Selected pet is outside the current filter. Its details remain here.</p></section></section>
</template>
<style scoped>
.pet-profile-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.pet-filters{display:flex;align-items:end;flex-wrap:wrap;gap:12px;margin-bottom:18px}.pet-filters label{display:grid;gap:6px;font-size:13px;font-weight:650;min-width:0;max-width:100%}.pet-profile-demo input,.pet-profile-demo select{width:100%;min-width:0;box-sizing:border-box;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.pet-profile-demo select{appearance:auto}.pet-profile-demo button{padding:8px 10px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.pet-profile-demo :is(input,select,button):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.pet-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.pet-grid article{min-width:0;padding:14px;border:1px solid var(--vp-c-divider);border-radius:10px;overflow-wrap:anywhere}.pet-grid h3{font-size:17px;margin:12px 0 8px}.pet-grid p{font-size:13px}.pet-avatar{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;border:2px solid var(--vp-c-brand-1);background:var(--vp-c-brand-soft);font-weight:700}.pet-status{background:var(--vp-c-bg-soft);padding:8px;border-radius:8px}.pet-grid button[aria-pressed=true]{outline:2px solid var(--vp-c-brand-1);outline-offset:2px}.pet-detail{margin-top:16px;padding:16px;background:var(--vp-c-bg-soft);border-radius:10px;animation:pet-detail-in .18s ease-out;overflow-wrap:anywhere}.pet-detail h3{margin:0 0 14px}.pet-detail dl>div{display:grid;grid-template-columns:90px minmax(0,1fr);gap:12px;margin:8px 0;font-size:13px}.pet-detail dd{margin:0}.pet-hidden,.pet-empty{padding:10px;border:1px solid var(--vp-c-divider);border-radius:8px}@keyframes pet-detail-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}@media(max-width:850px){.pet-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.pet-detail{animation:none}}
</style>
